"""Reusable tested-layout hex display component for the existing gate library.

Keep this file beside your main gate_templates.py, then register it after GATES:
    from sevenseg_hex_template import make_sevenseg_hex
    GATES["SEVENSEG_HEX"] = make_sevenseg_hex(Block, Terminal, GateTemplate)

The caller supplies its existing classes; no duplicate class definitions or
datapack execution commands are included. outputs={} is required by the
existing GateTemplate constructor and defines no output terminals.
"""

